import javax.crypto.*;import java.util.*;import java.nio.charset.*;
public class DES{public static void main(String[]x)throws Exception{Scanner s=new Scanner(System.in);System.out.print("Enter message: ");String m=s.nextLine();SecretKey k=KeyGenerator.getInstance("DES").generateKey();Cipher c=Cipher.getInstance("DES/ECB/PKCS5Padding");c.init(Cipher.ENCRYPT_MODE,k);byte[]e=c.doFinal(m.getBytes(StandardCharsets.UTF_8));c.init(Cipher.DECRYPT_MODE,k);System.out.println("Encrypted (Base64): "+Base64.getEncoder().encodeToString(e));System.out.println("Decrypted: "+new String(c.doFinal(e),StandardCharsets.UTF_8));}}
